// Reference data shipped with the client: every AIRAC cycle in src/data/ref/cycles (generated by
// tools/build_ref.ts; do not edit the JSON), and the one in effect today chosen when the page loads, so a cycle
// shipped ahead of its date takes over on that date with no deployment (a page open across the change offers a
// reload: AiracWatch). The same records are in the ref_* tables for the API (GET /api/ref/…), chosen by the same
// rule (api/_lib/airac.ts).
import { aerodromeIndex } from '../../shared/aerodrome';
import {
  airacDay,
  cycleOn,
  type RefAdAirspace,
  type RefAerodrome,
  type RefAirspace,
  type RefArea,
  type RefAtcUnit,
  type RefBundle,
  type RefFir,
  type RefFis,
  type RefNavaid,
  type RefRunway,
  type RefSunTable,
  type RefVfrPoint,
  type RefVfrRoute,
} from '../../shared/ref';
import { CYCLES } from './cycles';
// Not per cycle: tools/build_fir.ts (ENR 2.1 + OpenStreetMap land borders), client only.
import firJson from './fir.json';

/** The cycle in effect when this page loaded. */
export const CYCLE = cycleOn(CYCLES, airacDay());
/** The AIRAC in effect at a time (by the clock: a page open across a cycle's date sees the change here). */
export const airacInEffect = (now: number = Date.now()) => cycleOn(CYCLES, airacDay(now)).airac;
/** Epoch ms (0000 UTC) the next shipped cycle takes effect; null when none is shipped. */
export const NEXT_AIRAC_AT: number | null =
  CYCLES.map((c) => Date.parse(c.airac.effective + 'T00:00:00Z'))
    .filter((t) => t > Date.parse(CYCLE.airac.effective + 'T00:00:00Z'))
    .sort((a, b) => a - b)[0] ?? null;

export const AIRAC = CYCLE.airac;
export const AERODROMES: RefAerodrome[] = CYCLE.aerodromes;
export const RUNWAYS: RefRunway[] = CYCLE.runways;
export const AIRSPACES: RefAirspace[] = CYCLE.airspaces;
export const FIS: RefFis = CYCLE.fis;
export const VFR_POINTS: RefVfrPoint[] = CYCLE.vfrPoints;
export const VFR_ROUTES: RefVfrRoute[] = CYCLE.vfrRoutes;
export const ATC_UNITS: RefAtcUnit[] = CYCLE.atcUnits;
/** Aerodrome CTRs and ATZs (AD 2.17 / AD 1.6.N.17). */
export const AD_AIRSPACES: RefAdAirspace[] = CYCLE.adAirspaces;
/** The LGGG FIR boundary and the ATHINAI / MAKEDONIA line. */
export const FIR = firJson as unknown as RefFir;
/** ENR 5.1 / 5.2 / 5.3 areas (prohibited, restricted, danger, military, other activities). */
export const AREAS: RefArea[] = CYCLE.areas;
/** Radio navigation aids (VOR, VOR/DME, NDB, locators). */
export const NAVAIDS: RefNavaid[] = CYCLE.navaids;
/** AIP GEN 2.7 sunset tables keyed by ICAO. */
export const SUN_TABLES: Record<string, RefSunTable> = CYCLE.sun;

export const REF: RefBundle = {
  airac: AIRAC,
  aerodromes: AERODROMES,
  runways: RUNWAYS,
  airspaces: AIRSPACES,
  fis: FIS,
  vfrPoints: VFR_POINTS,
  vfrRoutes: VFR_ROUTES,
  atcUnits: ATC_UNITS,
  adAirspaces: AD_AIRSPACES,
  areas: AREAS,
  fir: FIR,
  navaids: NAVAIDS,
};

const index = aerodromeIndex(AERODROMES);
/** Aerodrome by id or ICAO. */
export function aerodrome(idOrIcao: string | null | undefined): RefAerodrome | undefined {
  return index.find(idOrIcao);
}

const vfrById = new Map(VFR_POINTS.map((p) => [p.id, p]));
export function vfrPoint(id: string | null | undefined): RefVfrPoint | undefined {
  return id ? vfrById.get(id) : undefined;
}

/** Runway directions of an aerodrome. */
export function runwaysOf(aerodromeId: string): RefRunway[] {
  return RUNWAYS.filter((r) => r.aerodromeId === aerodromeId);
}

/** The aerodrome a typed text names: exact id/ICAO, else a unique name match. */
export function resolveAerodrome(text: string): RefAerodrome | undefined {
  return index.resolve(text);
}

/** Suggestions for a query: ICAO prefix matches first, then name matches. */
export function searchAerodromes(q: string, limit = 8): RefAerodrome[] {
  const u = q.trim().toUpperCase();
  if (!u) return [];
  const score = (a: RefAerodrome) => {
    const code = (a.icao || a.id).toUpperCase();
    if (code === u) return 0;
    if (code.startsWith(u)) return 1;
    if (a.name.toUpperCase().split(/[\s/,-]+/).some((w) => w.startsWith(u))) return 2;
    if (a.name.toUpperCase().includes(u)) return 3;
    return 9;
  };
  return AERODROMES.map((a) => [score(a), a] as const)
    .filter(([s]) => s < 9)
    .sort((x, y) => x[0] - y[0] || (x[1].icao ? 0 : 1) - (y[1].icao ? 0 : 1) || x[1].name.localeCompare(y[1].name))
    .slice(0, limit)
    .map(([, a]) => a);
}
